@@ -0,0 +1,19 @@
+const test = require('node:test');
+const assert = require('node:assert/strict');
+const { getDefaults } = require('../lib/settings');
+const { createCustomer } = require('../lib/customers');
+const { formatTotal } = require('../lib/money');
+
+test('creating a customer does not change the global defaults', () => {
+  createCustomer({ id: 'c2', name: 'Bo', prefs: { currency: 'USD', precision: 0 } });
+  assert.equal(getDefaults().currency, 'EUR');
+  assert.equal(getDefaults().precision, 2);
+  assert.equal(formatTotal(100), '1.00 EUR');
+});
+
+test('getDefaults returns an independent copy each call', () => {
+  const a = getDefaults();
+  a.currency = 'JPY';
+  assert.notEqual(getDefaults(), a);
+  assert.equal(getDefaults().currency, 'EUR');
+});

